import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"2.3 起草、审批与外部写入","description":"先草稿、再审批、最后只执行一次外部写入。","frontmatter":{"title":"2.3 起草、审批与外部写入","description":"先草稿、再审批、最后只执行一次外部写入。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2/2-3.md","filePath":"delivery/stage-2/2-3.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-2/2-3.md"};function o(n,a,s,d,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_2-3-起草、审批与外部写入" tabindex="-1">2.3 起草、审批与外部写入 <a class="header-anchor" href="#_2-3-起草、审批与外部写入" aria-label="Permalink to &quot;2.3 起草、审批与外部写入&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 草稿可编辑、保存、丢弃；提交后生成一次性、短时有效审批；批准后由效果账本写入本地发件箱，或在配置 SMTP 账户后提交真实发送审批并保存回执；拒绝或失效会同步草稿状态。</li><li><strong>仍未完成：</strong> 未配置 SMTP 时只写本机 <code>.hearth/outbox</code>；真实账户、退信与垃圾邮件语义、附件选择尚未验收或实现；日历和其他外部系统写入未实现。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 能在用户确认后发送邮件、修改日历或写入其他工作系统，并保证同一次操作不会重复执行。先用测试账户跑通，再接触真实账户。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先生成草稿，不直接发送；草稿要能修改、保存和丢弃。</li><li>审批页必须展示准确的对象、账户、内容、附件、影响和是否可撤销。</li><li>审批只在短时间内有效，并且只能使用一次；用户拒绝后不执行。</li><li>先用测试账户完成“读取—起草—审批—发送或写入—回执”的完整流程。</li><li>发送或写入后保存回执；失败时说明是否可能已经执行，并提供核对和补救方式。</li><li>只把任务真正需要的背景信息交给执行过程，并显示使用了哪些信息。</li><li>没有隔离措施时，不直接接管用户的主账户。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
